import{_ as r,o as t,c as p,a6 as e}from"./chunks/framework.Bd7kzaCy.js";const _=JSON.parse('{"title":"Xikari-条件结构与转化论","description":"","frontmatter":{"title":"Xikari-条件结构与转化论"},"headers":[],"relativePath":"theory/index.md","filePath":"theory/index.md"}'),o={name:"theory/index.md"};function i(h,a,l,k,n,d){return t(),p("div",null,[...a[0]||(a[0]=[e('<div class="theory-source"><h1 id="book" tabindex="-1">Xikari-条件结构与转化论 <a class="header-anchor" href="#book" aria-label="Permalink to &quot;Xikari-条件结构与转化论 {#book}&quot;">​</a></h1><p>Xikari 著</p><p>对象 条件 作用与有限行动</p><p>2026年10月</p><h2 id="reading-scope" tabindex="-1">范围与阅读方式 <a class="header-anchor" href="#reading-scope" aria-label="Permalink to &quot;范围与阅读方式 {#reading-scope}&quot;">​</a></h2><p>本书讨论经验对象如何形成结构、通过哪些关系运转，以及条件与事件怎样改变其状态。结构判断始终对应具体对象、问题、时间窗和可用材料；不同判断能否连接，取决于其表示、证据、机制、资源与权限条件。全书分别展开结构解释、事件推演、条件前瞻和有限选择，使领域知识能够在保留自身对象与方法的同时互相核对。共同主线是：辨明哪些条件支撑对象与关系，哪些作用能够跨期传递，以及哪些区别必须在表示和行动转换中保留。</p><p>通用层面向广义经验世界。人类行动、意义、责任和授权进入各自的特化层，不能被反向投射为自然过程的共同目的。行动者与多圈层的联合表示，只在能够保留任务必要区别时使用。理解可以成为终点；有据的局部答案不必等待全部问题解决，复杂程度也不构成解释或前瞻能力。</p><p>涉及未来判断时，需要说明目标、期限、基线与失败条件；涉及方案推荐时，需要公开规范前提和代价；进入现实采用与执行时，还须取得适用的保护、复核和授权。定义、形式证明、教学情景、领域经验与实际使用效果分别承担证据责任，不能相互代证。</p><p>第一、二部分说明阅读方法和证据责任；第三至第六部分展开通用语法、条件命题、经验检验、尺度变换与运转机制；第七至第十一部分处理人的经验、集体原型、行动者、多圈层与动态推演；第十二至第十六部分讨论前瞻、选择、工具、规范、干涉和治理。附录A提供人类变量的完整接口，附录B给出术语索引，附录C呈现共同方法与自含形式论证，附录D连接32个领域的解释与应用。</p><h2 id="contents" tabindex="-1">分部目录 <a class="header-anchor" href="#contents" aria-label="Permalink to &quot;分部目录 {#contents}&quot;">​</a></h2><p><a href="/xi-kari-skill/handbook/theory/part-01.html#part_1">第一部分 导读</a></p><p><a href="/xi-kari-skill/handbook/theory/part-02.html#part_2">第二部分　边界与方法</a></p><p><a href="/xi-kari-skill/handbook/theory/part-03.html#part_3">第三部分　通用结构语法</a></p><p><a href="/xi-kari-skill/handbook/theory/part-04.html#part_4">第四部分　经验问题、结果合同与条件形式命题</a></p><p><a href="/xi-kari-skill/handbook/theory/part-05.html#part_5">第五部分　跨尺度与跨圈层变换</a></p><p><a href="/xi-kari-skill/handbook/theory/part-06.html#part_6">第六部分　运转与演化</a></p><p><a href="/xi-kari-skill/handbook/theory/part-07.html#part_7">第七部分　人类结构化世界</a></p><p><a href="/xi-kari-skill/handbook/theory/part-08.html#part_8">第八部分　人类状态原型</a></p><p><a href="/xi-kari-skill/handbook/theory/part-09.html#part_9">第九部分　行动者状态与人格假设</a></p><p><a href="/xi-kari-skill/handbook/theory/part-10.html#part_10">第十部分　多圈层对象与联合状态</a></p><p><a href="/xi-kari-skill/handbook/theory/part-11.html#part_11">第十一部分　事件驱动的动态推演</a></p><p><a href="/xi-kari-skill/handbook/theory/part-12.html#part_12">第十二部分　条件前瞻与有限选择</a></p><p><a href="/xi-kari-skill/handbook/theory/part-13.html#part_13">第十三部分　接口与工具</a></p><p><a href="/xi-kari-skill/handbook/theory/part-14.html#part_14">第十四部分　规范选择</a></p><p><a href="/xi-kari-skill/handbook/theory/part-15.html#part_15">第十五部分　干涉与应用</a></p><p><a href="/xi-kari-skill/handbook/theory/part-16.html#part_16">第十六部分　治理</a></p><p><a href="/xi-kari-skill/handbook/theory/appendix-a/#part_17">附录A　人类变量接口卡册</a></p><p><a href="/xi-kari-skill/handbook/theory/appendix-b.html#part_18">附录B　编号体系与术语总表</a></p><p><a href="/xi-kari-skill/handbook/theory/appendix-c.html#part_19">附录C 共同方法内核与跨学科桥接</a></p><p><a href="/xi-kari-skill/handbook/theory/appendix-d/#part_20">附录D　领域解释与应用图谱</a></p><p><a href="/xi-kari-skill/handbook/theory/references.html#part_21">参考文献</a></p><p>本书的基本承诺是给出可核对的分析语言和有条件的论证，不预设四个经验问题族足以演绎全部领域知识。形式命题的证明、实例证据的支持和整体方法的实际效益各有自己的判断标准。适用领域扩展时，可以增加领域机制，也可以让更简洁且充分的方法接管。</p></div>',1)])])}const x=r(o,[["render",i]]);export{_ as __pageData,x as default};
